from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r, c) not in seen:
                q = [(r, c)]
                seen.add((r, c))
                obj = []
                while q:
                    x, y = q.pop()
                    obj.append((x, y, color))
                    for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            q.append((nx, ny))
                objects.append(obj)
    objects.sort(key=lambda obj: max(c for _, c, _ in obj), reverse=True)
    out = [[0] * w for _ in range(h)]
    for obj in objects:
        shift = 0
        while True:
            nxt = shift + 1
            if any(c + nxt >= w or out[r][c+nxt] for r, c, _ in obj):
                break
            shift = nxt
        for r, c, color in obj:
            out[r][c+shift] = color
    return out
